    t[12] = VADD(t[12], VSRA(t[11], LIMB_LEN));
    t[13] = VADD(t[13], VSRA(t[12], LIMB_LEN));
    t[14] = VADD(t[14], VSRA(t[13], LIMB_LEN));
    t[15] = VADD(t[15], VSRA(t[14], LIMB_LEN));
